export enum SafetyState {
  SAFE = 'SAFE',
  WARNING = 'WARNING',
  CRITICAL = 'CRITICAL'
}

export interface DriverMetrics {
  ear: number; // Eye Aspect Ratio
  blinkRate: number;
  closureDuration: number;
  headPose: {
    pitch: number;
    yaw: number;
    roll: number;
  };
  stressLevel: number;
  distractionLevel: number;
}

export interface SafetyAssessment {
  score: number;
  state: SafetyState;
  explanation: string;
  metrics: DriverMetrics;
  timestamp: number;
}

export interface Poi {
  id: string;
  name: string;
  type: 'Rest Area' | 'Gas Station' | 'Coffee Shop' | 'Hospital';
  distance: string;
  time: string;
  coordinates: { lat: number; lng: number };
}

import { GoogleGenAI, Type } from "@google/genai";
import { SYSTEM_INSTRUCTION } from "../constants";
import { SafetyAssessment, SafetyState, DriverMetrics } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const analyzeDriverState = async (base64Image: string): Promise<SafetyAssessment> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { inlineData: { data: base64Image, mimeType: 'image/jpeg' } },
          { text: "Analyze this driver for safety metrics. Return JSON." }
        ]
      },
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
      }
    });

    const result = JSON.parse(response.text || '{}');
    const metrics: DriverMetrics = result.metrics;

    // Safety Score Formula Logic (Task 2)
    // Fatigue = f(EAR, Closure Duration)
    // Distraction = f(Head Pose, Distraction Level)
    // Stress = result.stressLevel

    const fatiguePenalty = (metrics.ear < 0.2 ? 30 : 0) + (metrics.closureDuration > 1.5 ? 40 : 0);
    const distractionPenalty = metrics.distractionLevel * 0.4 + (Math.abs(metrics.headPose.yaw) > 20 ? 20 : 0);
    const stressPenalty = metrics.stressLevel * 0.2;

    let score = Math.max(0, 100 - (fatiguePenalty + distractionPenalty + stressPenalty));

    let state = SafetyState.SAFE;
    if (score < 40) state = SafetyState.CRITICAL;
    else if (score < 75) state = SafetyState.WARNING;

    return {
      score,
      state,
      explanation: result.explanation || "No detection anomalies found.",
      metrics,
      timestamp: Date.now()
    };
  } catch (error) {
    console.error("Analysis failed", error);
    throw error;
  }
};

export const generateAlertSpeech = async (message: string): Promise<string> => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text: `Say in a calm, helpful driver-safety voice: ${message}` }] }],
      config: {
        responseModalities: ["AUDIO"],
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: 'Kore' },
          },
        },
      },
    });
    return response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data || "";
  } catch (error) {
    console.error("TTS failed", error);
    return "";
  }
};

import React, { useRef, useEffect, useState } from 'react';

interface CameraPreviewProps {
  onFrame: (base64: string) => void;
  isActive: boolean;
  stateColor: string;
}

const CameraPreview: React.FC<CameraPreviewProps> = ({ onFrame, isActive, stateColor }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);

  useEffect(() => {
    async function setupCamera() {
      try {
        const s = await navigator.mediaDevices.getUserMedia({ 
            video: { width: 640, height: 480, facingMode: 'user' } 
        });
        setStream(s);
        if (videoRef.current) {
          videoRef.current.srcObject = s;
        }
      } catch (err) {
        console.error("Error accessing camera", err);
      }
    }
    setupCamera();
    return () => stream?.getTracks().forEach(t => t.stop());
  }, []);

  useEffect(() => {
    if (!isActive) return;

    const interval = setInterval(() => {
      if (videoRef.current && canvasRef.current) {
        const ctx = canvasRef.current.getContext('2d');
        if (ctx) {
          ctx.drawImage(videoRef.current, 0, 0, 640, 480);
          const base64 = canvasRef.current.toDataURL('image/jpeg', 0.5).split(',')[1];
          onFrame(base64);
        }
      }
    }, 5000); // Analyze every 5 seconds for simulation efficiency

    return () => clearInterval(interval);
  }, [isActive, onFrame]);

  return (
    <div className={`relative rounded-2xl overflow-hidden border-2 transition-colors duration-500 shadow-2xl ${stateColor}`}>
      <div className="scanline"></div>
      <video 
        ref={videoRef} 
        autoPlay 
        muted 
        playsInline 
        className="w-full h-full object-cover grayscale brightness-75 contrast-125"
      />
      <canvas ref={canvasRef} width="640" height="480" className="hidden" />

      {/* HUD Overlays */}
      <div className="absolute inset-0 pointer-events-none p-4 flex flex-col justify-between">
        <div className="flex justify-between items-start">
          <div className="bg-black/50 px-3 py-1 rounded text-[10px] mono tracking-widest uppercase border border-white/20">
            CAM_IN_01 // LIVE
          </div>
          <div className="flex gap-2">
             <div className="h-2 w-2 rounded-full bg-red-500 animate-pulse" />
             <span className="text-[10px] mono uppercase">Rec</span>
          </div>
        </div>

        <div className="flex justify-between items-end">
          <div className="space-y-1">
            <div className="h-1 w-12 bg-white/20" />
            <div className="h-1 w-8 bg-white/20" />
          </div>
          <div className="text-[10px] mono text-right">
             84.2234° N<br/>
             12.4412° W
          </div>
        </div>
      </div>

      {/* Decorative Corner Borders */}
      <div className="absolute top-0 left-0 w-8 h-8 border-t-2 border-l-2 border-white/30 rounded-tl-xl pointer-events-none" />
      <div className="absolute top-0 right-0 w-8 h-8 border-t-2 border-r-2 border-white/30 rounded-tr-xl pointer-events-none" />
      <div className="absolute bottom-0 left-0 w-8 h-8 border-b-2 border-l-2 border-white/30 rounded-bl-xl pointer-events-none" />
      <div className="absolute bottom-0 right-0 w-8 h-8 border-b-2 border-r-2 border-white/30 rounded-br-xl pointer-events-none" />
    </div>
  );
};

export default CameraPreview;

