            <span className="text-[10px] mono text-gray-500 uppercase">Uptime</span>
            <span className="text-xs font-bold text-white">00:42:12</span>
          </div>
        </div>
      </header>

      {/* Main Grid */}
      <main className="flex-1 grid grid-cols-12 gap-6 min-h-0">

        {/* Left: Metrics */}
        <div className="col-span-3 h-full">
           <MetricsPanel metrics={assessment?.metrics || { 
             ear: 0.32, blinkRate: 12, closureDuration: 0.1, headPose: { pitch: 0, yaw: 0, roll: 0 }, stressLevel: 15, distractionLevel: 5 
           }} />
        </div>

        {/* Center: Camera & Safety Score */}
