import { GoogleGenAI, Type } from "@google/genai";
import { SYSTEM_INSTRUCTION } from "../constants";
import { SafetyAssessment, SafetyState, DriverMetrics, AutonomyLevel } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const analyzeDrivingEnvironment = async (
  base64Image: string, 
  history: SafetyAssessment[]
): Promise<SafetyAssessment> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { inlineData: { data: base64Image, mimeType: 'image/jpeg' } },
          { text: `Analyze state. Previous Score: ${history[history.length-1]?.score || 100}. 
                   Evaluate for: Fatigue, Stress, Distraction, Cognitive Load. 
                   Suggest Mood-Adaptive Audio and Autonomy Level.` }
        ]
      },
      config: {
        systemInstruction: `${SYSTEM_INSTRUCTION} 
        Additionally, determine:
        7. cognitiveLoad (0-100)
        8. autonomyLevel (INFORM, SUGGEST, ASSIST, OVERRIDE)
        9. moodIntervention (string - specific audio/breathing advice)
        10. fingerprintDeviation (0-100 - deviation from baseline metrics)`,
        responseMimeType: "application/json",
      }
    });

    const result = JSON.parse(response.text || '{}');
    const metrics: DriverMetrics = result.metrics;

    let score = Math.max(0, 100 - (
      (metrics.distractionLevel * 0.5) + 
      (metrics.stressLevel * 0.3) + 
      (metrics.cognitiveLoad * 0.2) +
      (result.fingerprintDeviation || 0) * 0.1
    ));

    let state = SafetyState.SAFE;
    if (score < 30) state = SafetyState.CRITICAL;
    else if (score < 65) state = SafetyState.WARNING;

    return {
      score,
      state,
      autonomyLevel: result.autonomyLevel || AutonomyLevel.INFORM,
      explanation: result.explanation || "System nominal.",
      metrics: { ...metrics, cognitiveLoad: result.cognitiveLoad || 10 },
      intervention: result.moodIntervention,
      timestamp: Date.now()
    };
  } catch (error) {
    console.error("CogniIntelligence Failure", error);
    throw error;
  }
};

export const generateSpeech = async (text: string) => {
  const response = await ai.models.generateContent({
    model: "gemini-2.5-flash-preview-tts",
    contents: [{ parts: [{ text }] }],
    config: {
      responseModalities: ["AUDIO"],
      speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
    },
  });
  return response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data || "";
};

